def select_target(self, enemies, field):
    best = None
    best_key = 0
    for enemy in enemies:
        if not can_aim(self.kind.targets, enemy) or not self.in_range(enemy.position()):
            continue
        key = self.target_key(enemy, field)
        if best is None or key < best_key:
            best = enemy
            best_key = key
    return best
